    BaniLine(id = "aarti-13", gurmukhi = "ਹਰਿ ਚਰਣ ਕਮਲ ਮਕਰੰਦ. ਲੋਭਿਤ ਮਨੋ; ਅਨਦਿਨੋ ਮੋਹਿ ਆਹੀ ਪਿਆਸਾ ॥", transliteration = "har charan kamal makarand. lobhit mno; andino moh aahee piaasaa ||", translation = "My soul is enticed by the honey-sweet lotus feet of the Lord; night and day, I thirst for them.", hindi = "हरि चरण कमल मकरंद. लोभित मनो; अनदिनो मोहि आही पिआसा ॥", punjabi = "ਹੇ ਹਰੀ! ਤੇਰੇ ਚਰਨ-ਰੂਪ ਕੌਲ ਫੁੱਲਾਂ ਦੇ ਰਸ ਲਈ ਮੇਰਾ ਮਨ ਲਲਚਾਂਦਾ ਹੈ, ਹਰ ਰੋਜ਼ ਮੈਨੂੰ ਇਸੇ ਰਸ ਦੀ ਪਿਆਸ ਲੱਗੀ ਹੋਈ ਹੈ।", wordMeaning = "ਮਕਰੰਦ = ਫੁੱਲਾਂ ਦੀ ਵਿਚਲੀ ਧੂੜ {Pollen dust}, ਫੁੱਲਾਂ ਦਾ ਰਸ। ਮਨੋ = ਮਨ। ਅਨਦਿਨੋ = ਹਰ ਰੋਜ਼। ਮੋਹਿ = ਮੈਨੂੰ। ਆਹੀ = ਹੈ, ਰਹਿੰਦੀ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-14", gurmukhi = "ਕ੍ਰਿਪਾ ਜਲੁ ਦੇਹਿ. ਨਾਨਕ ਸਾਰਿੰਗ ਕਉ; ਹੋਇ ਜਾ ਤੇ. ਤੇਰੈ ਨਾਮਿ ਵਾਸਾ ॥੪॥੧॥੭॥੯॥", transliteration = "kripaa jal deh. naanak saaring kau; hoi jaa te. terai naam vaasaa ||4||1||7||9||", translation = "Bless Nanak, the thirsty song-bird, with the water of Your Mercy, that he may come to dwell in Your Name. ||4||1||7||9||", hindi = "क्रिपा जलु देहि. नानक सारिंग कउ; होइ जा ते. तेरै नामि वासा ॥४॥१॥७॥९॥", punjabi = "ਮੈਨੂੰ ਨਾਨਕ ਪਪੀਹੇ ਨੂੰ ਆਪਣੀ ਮੇਹਰ ਦਾ ਜਲ ਦੇਹ, ਜਿਸ (ਦੀ ਬਰਕਤਿ) ਨਾਲ ਮੈਂ ਤੇਰੇ ਨਾਮ ਵਿਚ ਟਿਕਿਆ ਰਹਾਂ ॥੪॥੧॥੭॥੯॥", wordMeaning = "ਸਾਰਿੰਗ = ਪਪੀਹਾ। ਜਾ ਤੇ = ਜਿਸ ਨਾਲ। ਤੇਰੈ ਨਾਮਿ = ਤੇਰੇ ਨਾਮ ਵਿਚ ॥੪॥੧॥੭॥੯॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-15", gurmukhi = "ਨਾਮੁ ਤੇਰੋ ਆਰਤੀ ਮਜਨੁ ਮੁਰਾਰੇ ॥", transliteration = "naam tero aartee majan muraare ||", translation = "Your Name, Lord, is my adoration and cleansing bath.", hindi = "नामु तेरो आरती मजनु मुरारे ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! (ਅੰਞਾਣ ਲੋਕ ਮੂਰਤੀਆਂ ਦੀ ਆਰਤੀ ਕਰਦੇ ਹਨ, ਪਰ ਮੇਰੇ ਲਈ) ਤੇਰਾ ਨਾਮ (ਤੇਰੀ) ਆਰਤੀ ਹੈ, ਤੇ ਤੀਰਥਾਂ ਦਾ ਇਸ਼ਨਾਨ ਹੈ।", wordMeaning = "ਆਰਤੀ = {Skt. आरति = Waving lights before an image} ਥਾਲ ਵਿਚ ਫੁੱਲ ਰੱਖ ਕੇ ਜਗਦਾ ਦੀਵਾ ਰੱਖ ਕੇ ਚੰਦਨ ਆਦਿਕ ਸੁਗੰਧੀਆਂ ਲੈ ਕੇ ਕਿਸੇ ਮੂਰਤੀ ਅੱਗੇ ਉਹ ਥਾਲ ਹਿਲਾਈ ਜਾਣਾ ਤੇ ਉਸ ਦੀ ਉਸਤਤਿ ਵਿਚ ਭਜਨ ਗਾਉਣੇ = ਇਹ ਉਸ ਮੂਰਤੀ ਦੀ ਆਰਤੀ ਕਹੀ ਜਾਂਦੀ ਹੈ। ਮੁਰਾਰੇ = ਹੇ ਮੁਰਾਰਿ! {ਮੁਰ-ਅਰਿ। ਅਰਿ = ਵੈਰੀ, ਮੁਰ ਦੈਂਤ ਦਾ ਵੈਰੀ। ਕ੍ਰਿਸ਼ਨ ਜੀ ਦਾ ਨਾਮ ਹੈ} ਹੇ ਪਰਮਾਤਮਾ!", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-16", gurmukhi = "ਹਰਿ ਕੇ ਨਾਮ ਬਿਨੁ; ਝੂਠੇ ਸਗਲ ਪਾਸਾਰੇ ॥੧॥ ਰਹਾਉ ॥", transliteration = "har ke naam bin; jhoothe sagal paasaare ||1|| rhaau ||", translation = "Without the Name of the Lord, all ostentatious displays are useless. ||1||Pause||", hindi = "हरि के नाम बिनु; झूठे सगल पासारे ॥१॥ रहाउ ॥", punjabi = "(ਹੇ ਭਾਈ!) ਪਰਮਾਤਮਾ ਦੇ ਨਾਮ ਤੋਂ ਖੁੰਝ ਕੇ ਹੋਰ ਸਾਰੇ ਅਡੰਬਰ ਕੂੜੇ ਹਨ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਪਾਸਾਰੇ = ਖਿਲਾਰੇ, ਅਡੰਬਰ {ਨੋਟ: ਉਹਨਾਂ ਅਡੰਬਰਾਂ ਦਾ ਜ਼ਿਕਰ ਬਾਕੀ ਦੇ ਸ਼ਬਦ ਵਿਚ ਹੈ: ਚੰਦਨ ਚੜ੍ਹਾਉਣਾ, ਦੀਵਾ, ਮਾਲਾ, ਨੈਵੇਦ ਦਾ ਭੋਗ} ॥੧॥ ਰਹਾਉ ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-17", gurmukhi = "ਨਾਮੁ ਤੇਰੋ ਆਸਨੋ. ਨਾਮੁ ਤੇਰੋ ਉਰਸਾ; ਨਾਮੁ ਤੇਰਾ ਕੇਸਰੋ. ਲੇ ਛਿਟਕਾਰੇ ॥", transliteration = "naam tero aasno. naam tero ursaa; naam teraa kesro. le chhitkaare ||", translation = "Your Name is my prayer mat, and Your Name is the stone to grind the sandalwood. Your Name is the saffron which I take and sprinkle in offering to You.", hindi = "नामु तेरो आसनो. नामु तेरो उरसा; नामु तेरा केसरो. ले छिटकारे ॥", punjabi = "ਤੇਰਾ ਨਾਮ (ਮੇਰੇ ਲਈ ਪੰਡਿਤ ਵਾਲਾ) ਆਸਨ ਹੈ (ਜਿਸ ਉੱਤੇ ਬੈਠ ਕੇ ਉਹ ਮੂਰਤੀ ਦੀ ਪੂਜਾ ਕਰਦਾ ਹੈ), ਤੇਰਾ ਨਾਮ ਹੀ (ਚੰਦਨ ਘਸਾਉਣ ਲਈ) ਸਿਲ ਹੈ, (ਮੂਰਤੀ ਪੂਜਣ ਵਾਲਾ ਮਨੁੱਖ ਸਿਰ ਉੱਤੇ ਕੇਸਰ ਘੋਲ ਕੇ ਮੂਰਤੀ ਉੱਤੇ) ਕੇਸਰ ਛਿੜਕਦਾ ਹੈ, ਪਰ ਮੇਰੇ ਲਈ ਤੇਰਾ ਨਾਮ ਹੀ ਕੇਸਰ ਹੈ।", wordMeaning = "ਆਸਨੋ = ਉੱਨ ਆਦਿਕ ਦਾ ਕੱਪੜਾ ਜਿਸ ਤੇ ਬੈਠ ਕੇ ਮੂਰਤੀ ਦੀ ਪੂਜਾ ਕੀਤੀ ਜਾਂਦੀ ਹੈ। ਉਰਸਾ = ਚੰਦਨ ਰਗੜਨ ਵਾਲੀ ਸਿਲ। ਲੇ = ਲੈ ਕੇ। ਛਿਟਕਾਰੇ = ਛਿੜਕਾਈਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-18", gurmukhi = "ਨਾਮੁ ਤੇਰਾ ਅੰਭੁਲਾ. ਨਾਮੁ ਤੇਰੋ ਚੰਦਨੋ; ਘਸਿ ਜਪੇ. ਨਾਮੁ ਲੇ, ਤੁਝਹਿ ਕਉ ਚਾਰੇ ॥੧॥", transliteration = "naam teraa ambhulaa. naam tero chandno; ghas jpe. naam le, tujhah kau chaare ||1||", translation = "Your Name is the water, and Your Name is the sandalwood. The chanting of Your Name is the grinding of the sandalwood. I take it and offer all this to You. ||1||", hindi = "नामु तेरा अंभुला. नामु तेरो चंदनो; घसि जपे. नामु ले, तुझहि कउ चारे ॥१॥", punjabi = "ਹੇ ਮੁਰਾਰਿ! ਤੇਰਾ ਨਾਮ ਹੀ ਪਾਣੀ ਹੈ, ਨਾਮ ਹੀ ਚੰਦਨ ਹੈ, (ਇਸ ਨਾਮ-ਚੰਦਨ ਨੂੰ ਨਾਮ-ਪਾਣੀ ਨਾਲ) ਘਸਾ ਕੇ, ਤੇਰੇ ਨਾਮ ਦਾ ਸਿਮਰਨ-ਰੂਪ ਚੰਦਨ ਹੀ ਮੈਂ ਤੇਰੇ ਉੱਤੇ ਲਾਉਂਦਾ ਹਾਂ ॥੧॥", wordMeaning = "ਅੰਭੁਲਾ = {Skt. अंभस् = water} ਪਾਣੀ। ਜਪੇ = ਜਪਿ, ਜਪ ਕੇ। ਤੁਝਹਿ ਕਉ = ਤੈਨੂੰ ਹੀ। ਚਾਰੇ = ਚੜ੍ਹਾਈਦਾ ਹੈ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-19", gurmukhi = "ਨਾਮੁ ਤੇਰਾ ਦੀਵਾ. ਨਾਮੁ ਤੇਰੋ ਬਾਤੀ; ਨਾਮੁ ਤੇਰੋ ਤੇਲੁ. ਲੇ ਮਾਹਿ ਪਸਾਰੇ ॥", transliteration = "naam teraa deevaa. naam tero baatee; naam tero tel. le maah psaare ||", translation = "Your Name is the lamp, and Your Name is the wick. Your Name is the oil I pour into it.", hindi = "नामु तेरा दीवा. नामु तेरो बाती; नामु तेरो तेलु. ले माहि पसारे ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਤੇਰਾ ਨਾਮ ਦੀਵਾ ਹੈ, ਨਾਮ ਹੀ (ਦੀਵੇ ਦੀ) ਵੱਟੀ ਹੈ, ਨਾਮ ਹੀ ਤੇਲ ਹੈ, ਜੋ ਲੈ ਕੇ ਮੈਂ (ਨਾਮ-ਦੀਵੇ ਵਿਚ) ਪਾਇਆ ਹੈ;", wordMeaning = "ਬਾਤੀ = ਵੱਟੀ (ਦੀਵੇ ਦੀ)। ਮਾਹਿ = ਦੀਵੇ ਮਾਹਿ, ਦੀਵੇ ਵਿਚ। ਪਸਾਰੇ = ਪਾਈਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-20", gurmukhi = "ਨਾਮ ਤੇਰੇ ਕੀ ਜੋਤਿ ਲਗਾਈ; ਭਇਓ ਉਜਿਆਰੋ ਭਵਨ ਸਗਲਾਰੇ ॥੨॥", transliteration = "naam tere kee jot lgaaee; bhaio ujiaaro bhavan saglaare ||2||", translation = "Your Name is the light applied to this lamp, which enlightens and illuminates the entire world. ||2||", hindi = "नाम तेरे की जोति लगाई; भइओ उजिआरो भवन सगलारे ॥२॥", punjabi = "ਮੈਂ ਤੇਰੇ ਨਾਮ ਦੀ ਹੀ ਜੋਤਿ ਜਗਾਈ ਹੈ (ਜਿਸ ਦੀ ਬਰਕਤਿ ਨਾਲ) ਸਾਰੇ ਭਵਨਾਂ ਵਿਚ ਚਾਨਣ ਹੋ ਗਿਆ ਹੈ ॥੨॥", wordMeaning = "ਉਜਿਆਰੋ = ਚਾਨਣ। ਸਗਲਾਰੇ = ਸਾਰੇ। ਭਵਨ = ਭਵਨਾਂ ਵਿਚ, ਮੰਡਲਾਂ ਵਿਚ ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-21", gurmukhi = "ਨਾਮੁ ਤੇਰੋ ਤਾਗਾ. ਨਾਮੁ ਫੂਲ ਮਾਲਾ; ਭਾਰ ਅਠਾਰਹ ਸਗਲ ਜੂਠਾਰੇ ॥", transliteration = "naam tero taagaa. naam phool maalaa; bhaar athaarah sagal joothaare ||", translation = "Your Name is the thread, and Your Name is the garland of flowers. The eighteen loads of vegetation are all too impure to offer to You.", hindi = "नामु तेरो तागा. नामु फूल माला; भार अठारह सगल जूठारे ॥", punjabi = "ਤੇਰਾ ਨਾਮ ਮੈਂ ਧਾਗਾ ਬਣਾਇਆ ਹੈ, ਨਾਮ ਨੂੰ ਹੀ ਮੈਂ ਫੁੱਲ ਤੇ ਫੁੱਲਾਂ ਦੀ ਮਾਲਾ ਬਣਾਇਆ ਹੈ, ਹੋਰ ਸਾਰੀ ਬਨਸਪਤੀ (ਜਿਸ ਤੋਂ ਲੋਕ ਫੁੱਲ ਲੈ ਕੇ ਮੂਰਤੀਆਂ ਅੱਗੇ ਭੇਟ ਧਰਦੇ ਹਨ; ਤੇਰੇ ਨਾਮ ਦੇ ਟਾਕਰੇ ਤੇ) ਜੂਠੀ ਹੈ।", wordMeaning = "ਤਾਗਾ = (ਮਾਲਾ ਪਰੋਣ ਲਈ) ਧਾਗਾ। ਭਾਰ ਅਠਾਰਹ = ਸਾਰੀ ਬਨਸਪਤੀ, ਜਗਤ ਦੀ ਸਾਰੀ ਬਨਸਪਤੀ ਦੇ ਹਰੇਕ ਕਿਸਮ ਦੇ ਬੂਟੇ ਦਾ ਇੱਕ ਇੱਕ ਪੱਤਰ ਲੈ ਕੇ ਇਕੱਠੇ ਕੀਤਿਆਂ ੧੮ ਭਾਰ ਬਣਦੇ ਹਨ; ਇੱਕ ਭਾਰ ਪੰਜ ਮਣ ਕੱਚੇ ਦਾ ਹੈ, ਇਹ ਪੁਰਾਣਾ ਖ਼ਿਆਲ ਚਲਿਆ ਆ ਰਿਹਾ ਹੈ। ਜੂਠਾਰੇ = ਜੂਠੇ, ਕਿਉਂਕਿ ਭੌਰੇ ਆਦਿਕਾਂ ਨੇ ਸੁੰਘੇ ਹੋਏ ਹਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-22", gurmukhi = "ਤੇਰੋ ਕੀਆ. ਤੁਝਹਿ ਕਿਆ ਅਰਪਉ; ਨਾਮੁ ਤੇਰਾ. ਤੁਹੀ ਚਵਰ ਢੋਲਾਰੇ ॥੩॥", transliteration = "tero keeaa. tujhah kiaa arapau; naam teraa. tuhee chavar dholaare ||3||", translation = "Why should I offer to You, that which You Yourself created? Your Name is the fan, which I wave over You. ||3||", hindi = "तेरो कीआ. तुझहि किआ अरपउ; नामु तेरा. तुही चवर ढोलारे ॥३॥", punjabi = "(ਇਹ ਸਾਰੀ ਕੁਦਰਤ ਤਾਂ ਤੇਰੀ ਬਣਾਈ ਹੋਈ ਹੈ) ਤੇਰੀ ਪੈਦਾ ਕੀਤੀ ਹੋਈ ਵਿਚੋਂ ਮੈਂ ਤੇਰੇ ਅੱਗੇ ਕੀਹ ਰੱਖਾਂ? (ਸੋ,) ਮੈਂ ਤੇਰਾ ਨਾਮ-ਰੂਪ ਚੌਰ ਹੀ ਤੇਰੇ ਉਤੇ ਝਲਾਉਂਦਾ ਹਾਂ। ਭਾਵ ਆਰਤੀ ਆਦਿਕ ਦੇ ਅਡੰਬਰ ਕੂੜੇ ਹਨ। ਸਿਮਰਨ ਹੀ ਜ਼ਿੰਦਗੀ ਦਾ ਸਹੀ ਰਸਤਾ ਹੈ ॥੩॥", wordMeaning = "ਅਰਪਉ = ਮੈਂ ਭੇਟਾ ਕਰਾਂ। ਤੁਹੀ = ਤੈਨੂੰ ਹੀ। ਢੋਲਾਰੇ = ਝੁਲਾਈਦਾ ਹੈ ॥੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-23", gurmukhi = "ਦਸ ਅਠਾ ਅਠਸਠੇ ਚਾਰੇ ਖਾਣੀ; ਇਹੈ ਵਰਤਣਿ ਹੈ ਸਗਲ ਸੰਸਾਰੇ ॥", transliteration = "das athaa athasthe chaare khaanee; ihai varatan hai sagal sansaare ||", translation = "The whole world is engrossed in the eighteen Puraanas, the sixty-eight sacred shrines of pilgrimage, and the four sources of creation.", hindi = "दस अठा अठसठे चारे खाणी; इहै वरतणि है सगल संसारे ॥", punjabi = "ਸਾਰੇ ਸੰਸਾਰ ਦੀ ਨਿੱਤ ਦੀ ਕਾਰ ਤਾਂ ਇਹ ਹੈ ਕਿ (ਤੇਰਾ ਨਾਮ ਭੁਲਾ ਕੇ) ਅਠਾਰਾਂ ਪੁਰਾਣਾਂ ਦੀਆਂ ਕਹਾਣੀਆਂ ਵਿਚ ਪਰਚੇ ਹੋਏ ਹਨ, ਅਠਾਹਠ ਤੀਰਥਾਂ ਦੇ ਇਸ਼ਨਾਨ ਨੂੰ ਹੀ ਪੁੰਨ-ਕਰਮ ਸਮਝ ਬੈਠੇ ਹਨ, ਤੇ, ਇਸ ਤਰ੍ਹਾਂ ਚਾਰ ਖਾਣੀਆਂ ਦੀਆਂ ਜੂਨਾਂ ਵਿਚ ਭਟਕ ਰਹੇ ਹਨ।", wordMeaning = "ਦਸ ਅਠਾ = ੧੮ ਪੁਰਾਣ। ਅਠਸਠੇ = ੬੮ ਤੀਰਥ। ਵਰਤਣਿ = ਨਿੱਤ ਦੀ ਕਾਰ, ਪਰਚਾ।", startsAtMs = 0L, endsAtMs = 0L),
