    BaniLine(id = "aarti-37", gurmukhi = "ਸੁੰਨ ਸੰਧਿਆ ਤੇਰੀ. ਦੇਵ ਦੇਵਾਕਰ; ਅਧਪਤਿ ਆਦਿ ਸਮਾਈ ॥", transliteration = "sunn sandhiaa teree. dev devaakar; adhapat aad smaaee ||", translation = "Hear my prayer, Lord; You are the Divine Light of the Divine, the Primal, All-pervading Master.", hindi = "सुंन संधिआ तेरी. देव देवाकर; अधपति आदि समाई ॥", punjabi = "ਹੇ ਦੇਵ! ਹੇ ਚਾਨਣ ਦੀ ਖਾਣ! ਹੇ ਜਗਤ ਦੇ ਮਾਲਕ! ਹੇ ਸਭ ਦੇ ਮੂਲ! ਹੇ ਸਰਬ ਵਿਆਪਕ ਪ੍ਰਭੂ! (ਤੂੰ ਮਾਇਆ ਤੋਂ ਰਹਿਤ ਹੈਂ, ਸੋ) ਮਾਇਆ ਦੇ ਫੁਰਨਿਆਂ ਵਲੋਂ ਮਨ ਨੂੰ ਸਾਫ਼ ਰੱਖਣਾ (ਤੇ ਤੇਰੇ ਚਰਨਾਂ ਵਿਚ ਹੀ ਜੁੜੇ ਰਹਿਣਾ) ਇਹ ਤੇਰੀ ਆਰਤੀ ਕਰਨੀ ਹੈ।", wordMeaning = "ਸੁੰਨ = ਸੁੰਞ, ਅਫੁਰ ਅਵਸਥਾ, ਮਾਇਆ ਦੇ ਮੋਹ ਦਾ ਕੋਈ ਫੁਰਨਾ ਮਨ ਵਿਚ ਨਾਹ ਉਠਣ ਵਾਲੀ ਅਵਸਥਾ। ਸੰਧਿਆ = (Skt. संध्या = The morning, noon and evening prayers of a Brahman) ਸਵੇਰੇ, ਦੁਪਹਰਿ ਤੇ ਸ਼ਾਮ ਵੇਲੇ ਦੀ ਪੂਜਾ ਜੋ ਹਰੇਕ ਬ੍ਰਾਹਮਣ ਲਈ ਕਰਨੀ ਯੋਗ ਹੈ। ਦੇਵਾਕਰ = ਹੇ ਚਾਨਣ ਦੀ ਖਾਣ! (ਦੇਵ = ਆਕਰ)। ਅਧਪਤਿ = ਹੇ ਮਾਲਕ! ਆਦਿ = ਹੇ ਸਾਰੇ ਜਗਤ ਦੇ ਮੂਲ! ਸਮਾਈ = ਹੇ ਸਰਬ-ਵਿਆਪਕ!", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-38", gurmukhi = "ਸਿਧ ਸਮਾਧਿ ਅੰਤੁ. ਨਹੀ ਪਾਇਆ; ਲਾਗਿ ਰਹੇ ਸਰਨਾਈ ॥੧॥", transliteration = "sidh smaadh ant. nhee paaiaa; laag rhe sarnaaee ||1||", translation = "The Siddhas in Samaadhi have not found Your limits. They hold tight to the Protection of Your Sanctuary. ||1||", hindi = "सिध समाधि अंतु. नही पाइआ; लागि रहे सरनाई ॥१॥", punjabi = "ਜੋਗ-ਅੱਭਿਆਸ ਵਿਚ ਨਿਪੁੰਨ ਜੋਗੀਆਂ ਨੇ ਸਮਾਧੀਆਂ ਲਾ ਕੇ ਭੀ ਤੇਰਾ ਅੰਤ ਨਹੀਂ ਲੱਭਾ ਉਹ ਆਖ਼ਰ ਤੇਰੀ ਸ਼ਰਨ ਲੈਂਦੇ ਹਨ ॥੧॥", wordMeaning = "ਸਿਧ = ਪੁੱਗੇ ਹੋਏ ਜੋਗੀ, ਜੋਗ-ਅਭਿਆਸ ਵਿਚ ਨਿਪੁੰਨ ਜੋਗੀ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-39", gurmukhi = "ਲੇਹੁ ਆਰਤੀ, ਹੋ ਪੁਰਖ ਨਿਰੰਜਨ; ਸਤਿਗੁਰ ਪੂਜਹੁ ਭਾਈ ॥", transliteration = "leh aartee, ho purakh niranjan; stigur poojah bhaaee ||", translation = "Worship and adoration of the Pure, Primal Lord comes by worshipping the True Guru, O Siblings of Destiny.", hindi = "लेहु आरती, हो पुरख निरंजन; सतिगुर पूजहु भाई ॥", punjabi = "ਗੁਰੂ ਦੇ ਦੱਸੇ ਹੋਏ ਰਾਹ ਤੇ ਤੁਰੋ, ਤੇ ਉਸ ਪ੍ਰਭੂ ਦੀ ਆਰਤੀ ਉਤਾਰੋ ਜੋ ਮਾਇਆ ਤੋਂ ਰਹਿਤ ਹੈ ਤੇ ਜੋ ਸਭ ਵਿਚ ਵਿਆਪਕ ਹੈ,", wordMeaning = "ਹੋ ਭਾਈ = ਹੇ ਭਾਈ! ਪੁਰਖ ਨਿਰੰਜਨ ਆਰਤੀ = ਮਾਇਆ-ਰਹਿਤ ਸਰਬ ਵਿਆਪਕ ਪ੍ਰਭੂ ਦੀ ਆਰਤੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-40", gurmukhi = "ਠਾਢਾ ਬ੍ਰਹਮਾ. ਨਿਗਮ ਬੀਚਾਰੈ; ਅਲਖੁ. ਨ ਲਖਿਆ ਜਾਈ ॥੧॥ ਰਹਾਉ ॥", transliteration = "thaadhaa brahmaa. nigam beechaarai; alakh. na lkhiaa jaaee ||1|| rhaau ||", translation = "Standing at His Door, Brahma studies the Vedas, but he cannot see the Unseen Lord. ||1||Pause||", hindi = "ठाढा ब्रहमा. निगम बीचारै; अलखु. न लखिआ जाई ॥१॥ रहाउ ॥", punjabi = "ਜਿਸ ਦੇ ਕੋਈ ਖ਼ਾਸ ਚਿਹਨ-ਚੱਕ੍ਰ ਨਹੀਂ ਹਨ, ਜਿਸ ਦੇ ਗੁਣ ਬਿਆਨ ਨਹੀਂ ਕੀਤੇ ਜਾ ਸਕਦੇ ਤੇ ਜਿਸ ਦੇ ਦਰ ਤੇ ਖਲੋਤਾ ਬ੍ਰਹਮਾ ਵੇਦ ਵਿਚਾਰ ਰਿਹਾ ਹੈ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਠਾਢਾ = ਖਲੋਤਾ ਹੋਇਆ। ਨਿਗਮ = ਵੇਦ। ਅਲਖੁ = (Skt. अलक्ष्य = having no particular marks) ਜਿਸ ਦੇ ਕੋਈ ਖ਼ਾਸ ਚਿਹਨ ਚੱਕ੍ਰ ਨਹੀਂ ॥੧॥ ਰਹਾਉ ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-41", gurmukhi = "ਤਤੁ ਤੇਲੁ, ਨਾਮੁ ਕੀਆ ਬਾਤੀ; ਦੀਪਕੁ ਦੇਹ, ਉਜੵਾਰਾ ॥", transliteration = "tat tel, naam keeaa baatee; deepak deh, ujyaaraa ||", translation = "With the oil of knowledge about the essence of reality, and the wick of the Naam, the Name of the Lord, this lamp illluminates my body.", hindi = "ततु तेलु, नामु कीआ बाती; दीपकु देह, उज्यारा ॥", punjabi = "(ਜਿਸ ਨੇ ਆਰਤੀ ਦਾ ਇਹ ਭੇਤ ਸਮਝਿਆ ਹੈ ਉਸ ਨੇ) ਗਿਆਨ ਨੂੰ ਤੇਲ ਬਣਾਇਆ ਹੈ, ਨਾਮ ਨੂੰ ਵੱਟੀ ਤੇ ਸਰੀਰ ਵਿਚ (ਨਾਮ ਦੇ) ਚਾਨਣ ਨੂੰ ਹੀ ਦੀਵਾ ਬਣਾਇਆ ਹੈ।", wordMeaning = "ਤਤੁ = ਗਿਆਨ। ਬਾਤੀ = ਵੱਟੀ। ਦੇਹ ਉਜ੍ਹਾਰਾ = ਸਰੀਰ ਵਿਚ (ਤੇਰੇ ਨਾਮ ਦਾ) ਚਾਨਣ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-42", gurmukhi = "ਜੋਤਿ ਲਾਇ ਜਗਦੀਸ ਜਗਾਇਆ; ਬੂਝੈ ਬੂਝਨਹਾਰਾ ॥੨॥", transliteration = "jot laai jagdees jgaaiaa; boojhai boojhanhaaraa ||2||", translation = "I have applied the Light of the Lord of the Universe, and lit this lamp. God the Knower knows. ||2||", hindi = "जोति लाइ जगदीस जगाइआ; बूझै बूझनहारा ॥२॥", punjabi = "ਇਹ ਦੀਵਾ ਉਸ ਨੇ ਜਗਤ ਦੇ ਮਾਲਕ ਪ੍ਰਭੂ ਦੀ ਜੋਤ (ਵਿਚ ਜੁੜ ਕੇ) ਜਗਾਇਆ ਹੈ। ਕੋਈ ਵਿਰਲਾ ਗਿਆਨਵਾਨ (ਪ੍ਰਭੂ ਦੀ ਆਰਤੀ ਦਾ ਭੇਤ) ਸਮਝਦਾ ਹੈ ॥੨॥", wordMeaning = "ਜਗਦੀਸ ਜੋਤਿ = ਜਗਦੀਸ ਦੇ ਨਾਮ ਦੀ ਜੋਤ। ਬੂਝਨਹਾਰਾ = ਗਿਆਨਵਾਨ ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-43", gurmukhi = "ਪੰਚੇ ਸਬਦ ਅਨਾਹਦ ਬਾਜੇ; ਸੰਗੇ ਸਾਰਿੰਗਪਾਨੀ ॥", transliteration = "panche sabad anaahad baaje; sange saaringpaanee ||", translation = "The Unstruck Melody of the Panch Shabad, the Five Primal Sounds, vibrates and resounds. I dwell with the Lord of the World.", hindi = "पंचे सबद अनाहद बाजे; संगे सारिंगपानी ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ! ਇਸ ਆਰਤੀ ਦੀ ਬਰਕਤਿ ਨਾਲ) ਤੂੰ ਮੈਨੂੰ ਅੰਗ-ਸੰਗ ਦਿੱਸ ਰਿਹਾ ਹੈਂ (ਤੇ ਮੇਰੇ ਅੰਦਰ ਇਕ ਐਸਾ ਆਨੰਦ ਬਣ ਰਿਹਾ ਹੈ, ਮਾਨੋ) ਪੰਜ ਹੀ ਕਿਸਮਾਂ ਦੇ ਸਾਜ਼ (ਮੇਰੇ ਅੰਦਰ) ਇੱਕ-ਰਸ ਵੱਜ ਰਹੇ ਹਨ।", wordMeaning = "ਪੰਚੇ ਸਬਦ = ਪੰਜ ਹੀ ਨਾਦ; ਪੰਜ ਕਿਸਮਾਂ ਦੇ ਸਾਜ਼ਾਂ ਦੀ ਆਵਾਜ਼, (ਪੰਜ ਕਿਸਮਾਂ ਦੇ ਸਾਜ਼ ਇਹ ਹਨ: ਤੰਤੀ ਸਾਜ਼, ਖੱਲ ਨਾਲ ਮੜ੍ਹੇ ਹੋਏ, ਧਾਤ ਦੇ ਬਣੇ ਹੋਏ, ਘੜਾ ਆਦਿਕ, ਫੂਕ ਮਾਰ ਕੇ ਵਜਾਣ ਵਾਲੇ ਸਾਜ਼। ਜਦੋਂ ਇਹ ਸਾਰੀਆਂ ਕਿਸਮਾਂ ਦੇ ਸਾਜ਼ ਰਲਾ ਕੇ ਵਜਾਏ ਜਾਣ ਤਾਂ ਮਹਾਂ ਸੁੰਦਰ ਰਾਗ ਪੈਦਾ ਹੁੰਦਾ ਹੈ, ਜੋ ਮਨ ਨੂੰ ਮਸਤ ਕਰ ਦੇਂਦਾ ਹੈ)। ਅਨਾਹਦ = ਬਿਨਾ ਵਜਾਏ, ਇੱਕ-ਰਸ। ਸੰਗੇ = ਨਾਲ ਹੀ, ਅੰਦਰ ਹੀ (ਦਿੱਸ ਪੈਂਦਾ ਹੈ)। ਸਾਰਿੰਗਪਾਨੀ = (ਸਾਰਿੰਗ = ਧਨਖ। ਪਾਨੀ = ਹੱਥ) ਜਿਸ ਦੇ ਹੱਥ ਵਿਚ ਧਨਖ ਹੈ, ਜੋ ਸਾਰੇ ਜਗਤ ਦਾ ਨਾਸ ਕਰਨ ਵਾਲਾ ਭੀ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-44", gurmukhi = "ਕਬੀਰ ਦਾਸ. ਤੇਰੀ ਆਰਤੀ ਕੀਨੀ; ਨਿਰੰਕਾਰ ਨਿਰਬਾਨੀ ॥੩॥੫॥", transliteration = "kabeer daas. teree aartee keenee; nirankaar nirbaanee ||3||5||", translation = "Kabeer, Your slave, performs this Aartee, this lamp-lit worship service for You, O Formless Lord of Nirvaanaa. ||3||5||", hindi = "कबीर दास. तेरी आरती कीनी; निरंकार निरबानी ॥३॥५॥", punjabi = "ਹੇ ਵਾਸ਼ਨਾ-ਰਹਿਤ ਨਿਰੰਕਾਰ! ਹੇ ਸਾਰਿੰਗਪਾਣ! ਮੈਂ ਤੇਰੇ ਦਾਸ ਕਬੀਰ ਨੇ ਭੀ ਤੇਰੀ (ਇਹੋ ਜਿਹੀ ਹੀ) ਆਰਤੀ ਕੀਤੀ ਹੈ ॥੩॥੫॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-45", gurmukhi = "ਧੰਨਾ ॥", transliteration = "dhannaa ||", translation = "Dhannaa:", hindi = "धंना ॥", punjabi = "ਧੰਨਾ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-46", gurmukhi = "ਗੋਪਾਲ ਤੇਰਾ ਆਰਤਾ ॥", transliteration = "gopaal teraa aartaa ||", translation = "O Lord of the world, this is Your lamp-lit worship service.", hindi = "गोपाल तेरा आरता ॥", punjabi = "ਹੇ ਪ੍ਰਿਥਵੀ ਦੇ ਪਾਲਣ ਵਾਲੇ ਪ੍ਰਭੂ! ਮੈਂ ਤੇਰੇ ਦਰ ਦਾ ਮੰਗਤਾ ਹਾਂ (ਮੇਰੀਆਂ ਲੋੜਾਂ ਪੂਰੀਆਂ ਕਰ);", wordMeaning = "ਆਰਤਾ = ਲੋੜਵੰਦਾ, ਦੁਖੀਆ, ਮੰਗਤਾ {Skt. आर्तं}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-47", gurmukhi = "ਜੋ ਜਨ ਤੁਮਰੀ ਭਗਤਿ ਕਰੰਤੇ; ਤਿਨ ਕੇ ਕਾਜ ਸਵਾਰਤਾ ॥੧॥ ਰਹਾਉ ॥", transliteration = "jo jan tumree bhagat karante; tin ke kaaj svaartaa ||1|| rhaau ||", translation = "You are the Arranger of the affairs of those humble beings who perform Your devotional worship service. ||1||Pause||", hindi = "जो जन तुमरी भगति करंते; तिन के काज सवारता ॥१॥ रहाउ ॥", punjabi = "ਜੋ ਜੋ ਮਨੁੱਖ ਤੇਰੀ ਭਗਤੀ ਕਰਦੇ ਹਨ ਤੂੰ ਉਹਨਾਂ ਦੇ ਕੰਮ ਸਿਰੇ ਚਾੜ੍ਹਦਾ ਹੈਂ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-48", gurmukhi = "ਦਾਲਿ ਸੀਧਾ; ਮਾਗਉ ਘੀਉ ॥", transliteration = "daal seedhaa; maagau gheeu ||", translation = "Lentils, flour and ghee - these things, I beg of You.", hindi = "दालि सीधा; मागउ घीउ ॥", punjabi = "ਮੈਂ (ਤੇਰੇ ਦਰ ਤੋਂ) ਦਾਲ, ਆਟਾ ਤੇ ਘਿਉ ਮੰਗਦਾ ਹਾਂ,", wordMeaning = "ਸੀਧਾ = ਆਟਾ। ਮਾਗਉ = ਮੰਗਦਾ ਹਾਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-49", gurmukhi = "ਹਮਰਾ ਖੁਸੀ ਕਰੈ ਨਿਤ ਜੀਉ ॥", transliteration = "hamraa khusee krai nit jeeu ||", translation = "My mind shall ever be pleased.", hindi = "हमरा खुसी करै नित जीउ ॥", punjabi = "ਜੋ ਮੇਰੀ ਜਿੰਦ ਨੂੰ ਨਿੱਤ ਸੁਖੀ ਰੱਖੇ,", wordMeaning = "ਜੀਉ = ਜਿੰਦ, ਮਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-50", gurmukhi = "ਪਨੑੀਆ ਛਾਦਨੁ ਨੀਕਾ ॥", transliteration = "panheeaa chhaadan neekaa ||", translation = "Shoes, fine clothes,", hindi = "पन्हीआ छादनु नीका ॥", punjabi = "ਜੁੱਤੀ ਤੇ ਸੋਹਣਾ ਕੱਪੜਾ ਭੀ ਮੰਗਦਾ ਹਾਂ,", wordMeaning = "ਪਨ੍ਹ੍ਹੀਆ = ਜੁੱਤੀ {Skt. उपानह् }। ਛਾਦਨੁ = ਕਪੜਾ। ਨੀਕਾ = ਸੋਹਣਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-51", gurmukhi = "ਅਨਾਜੁ ਮਗਉ; ਸਤ ਸੀ ਕਾ ॥੧॥", transliteration = "anaaj magau; sat see kaa ||1||", translation = "And grain of seven kinds - I beg of You. ||1||", hindi = "अनाजु मगउ; सत सी का ॥१॥", punjabi = "ਤੇ ਸੱਤਾਂ ਸੀਆਂ ਦਾ ਅੰਨ ਭੀ (ਤੈਥੋਂ ਹੀ) ਮੰਗਦਾ ਹਾਂ ॥੧॥", wordMeaning = "ਸਤ ਸੀ ਕਾ ਅਨਾਜ = ਸੱਤ ਸੀਆਂ ਵਾਲਾ ਅੰਨ, ਉਹ ਅੰਨ ਜੋ ਪੈਲੀ ਨੂੰ ਸੱਤ ਵਾਰੀ ਵਾਹ ਕੇ ਪੈਦਾ ਕੀਤਾ ਹੋਵੇ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-52", gurmukhi = "ਗਊ ਭੈਸ ਮਗਉ ਲਾਵੇਰੀ ॥", transliteration = "gaoo bhais magau laaveree ||", translation = "A milk cow, and a water buffalo, I beg of You,", hindi = "गऊ भैस मगउ लावेरी ॥", punjabi = "ਹੇ ਗੋਪਾਲ! ਮੈਂ ਗਾਂ ਮਹਿੰ ਲਵੇਰੀ (ਭੀ) ਮੰਗਦਾ ਹਾਂ,", wordMeaning = "ਲਾਵੇਰੀ = ਦੁੱਧ ਦੇਣ ਵਾਲੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-53", gurmukhi = "ਇਕ ਤਾਜਨਿ ਤੁਰੀ ਚੰਗੇਰੀ ॥", transliteration = "ik taajan turee changeree ||", translation = "and a fine Turkestani horse.", hindi = "इक ताजनि तुरी चंगेरी ॥", punjabi = "ਤੇ ਇਕ ਚੰਗੀ ਅਰਬੀ ਘੋੜੀ ਭੀ ਚਾਹੀਦੀ ਹੈ।", wordMeaning = "ਤਾਜਨਿ ਤੁਰੀ = ਅਰਬੀ ਘੋੜੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-54", gurmukhi = "ਘਰ ਕੀ ਗੀਹਨਿ ਚੰਗੀ ॥", transliteration = "ghar kee geehan changee ||", translation = "A good wife to care for my home", hindi = "घर की गीहनि चंगी ॥", punjabi = "ਘਰ ਦੀ ਚੰਗੀ ਇਸਤ੍ਰੀ ਵੀ-", wordMeaning = "ਗੀਹਨਿ = {Skt. गृहिनी} ਇਸਤ੍ਰੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-55", gurmukhi = "ਜਨੁ ਧੰਨਾ ਲੇਵੈ ਮੰਗੀ ॥੨॥੪॥", transliteration = "jan dhannaa levai mangee ||2||4||", translation = "- Your humble servant Dhanna begs for these things, Lord. ||2||4||", hindi = "जनु धंना लेवै मंगी ॥२॥४॥", punjabi = "ਮੈਂ ਤੇਰਾ ਦਾਸ ਧੰਨਾ ਤੈਥੋਂ ਮੰਗ ਕੇ ਲੈਂਦਾ ਹਾਂ ॥੨॥੪॥", wordMeaning = "ਮੰਗੀ = ਮੰਗਿ, ਮੰਗ ਕੇ ॥੨॥੪॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-56", gurmukhi = "ਸ੍ਵੈਯਾ ॥", transliteration = "svaiyaa ||", translation = "SWAYYA", hindi = "स्वैया ॥", punjabi = "ਸ੍ਵੈਯਾ", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-57", gurmukhi = "ਪਾਂਇ ਗਹੇ ਜਬ ਤੇ ਤੁਮਰੇ ਤਬ ਤੇ ਕੋਊ ਆਂਖ ਤਰੇ ਨਹੀਂ ਆਨ︀ਯੋ ॥", transliteration = "paani ghe jab te tumre tab te kooo aankh tre nheen aan︀yo ||", translation = "O God! the day when I caught hold of your feet, I do not bring anyone else under my sight", hindi = "पांइ गहे जब ते तुमरे तब ते कोऊ आंख तरे नहीं आन︀यो ॥", punjabi = "ਜਦ ਤੋਂ ਤੁਹਾਡੇ ਚਰਨ ਫੜੇ ਹਨ ਤਦ ਤੋਂ ਮੈਂ (ਹੋਰ) ਕਿਸੇ ਨੂੰ ਅੱਖਾਂ ਹੇਠਾਂ ਨਹੀਂ ਲਿਆਉਂਦਾ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-58", gurmukhi = "ਰਾਮ ਰਹੀਮ ਪੁਰਾਨ ਕੁਰਾਨ; ਅਨੇਕ ਕਹੈਂ, ਮਤ ਏਕ ਨ ਮਾਨ︀ਯੋ ॥", transliteration = "raam rheem puraan kuraan; anek khain, mat ek na maan︀yo ||", translation = "None other is liked by me now   the Puranas and the Quran try to know Thee by the names of Ram and Rahim and talk about you through several stories,", hindi = "राम रहीम पुरान कुरान; अनेक कहैं, मत एक न मान︀यो ॥", punjabi = "ਰਾਮ, ਰਹੀਮ, ਪੁਰਾਨ ਅਤੇ ਕੁਰਾਨ ਨੇ ਅਨੇਕਾਂ ਮੱਤ ਕਹੇ ਗਏ ਹਨ। (ਪਰ ਮੈਂ ਕਿਸੇ) ਇਕ ਨੂੰ ਵੀ ਨਹੀਂ ਮੰਨਦਾ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-59", gurmukhi = "ਸਿੰਮ੍ਰਿਤ ਸਾਸਤ੍ਰ ਬੇਦ ਸਭੈ; ਬਹੁ ਭੇਦ ਕਹੈਂ, ਹਮ ਏਕ ਨ ਜਾਨ︀ਯੋ ॥", transliteration = "simrit saasatr bed sbhai; bah bhed khain, ham ek na jaan︀yo ||", translation = "The Simritis, Shastras and Vedas describe several mysteries of yours, but I do not agree with any of them.", hindi = "सिंम्रित सासत्र बेद सभै; बहु भेद कहैं, हम एक न जान︀यो ॥", punjabi = "ਸਮ੍ਰਿਤੀਆਂ, ਸ਼ਾਸਤ੍ਰ ਅਤੇ ਵੇਦ ਬਹੁਤ ਸਾਰੇ ਭੇਦ ਦੱਸਦੇ ਹਨ, ਪਰ ਮੈਂ ਇਕ ਵੀ ਨਹੀਂ ਜਾਣਿਆ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-60", gurmukhi = "ਸ੍ਰੀ ਅਸਿਪਾਨ, ਕ੍ਰਿਪਾ ਤੁਮਰੀ ਕਰਿ; ਮੈ ਨ ਕਹ︀ਯੋ, ਸਭ ਤੋਹਿ ਬਖਾਨ︀ਯੋ ॥੮੬੩॥", transliteration = "sree asipaan, kripaa tumree kar; mai na kah︀yo, sabh toh bkhaan︀yo ||863||", translation = "O sword-wielder God! This all has been described by Thy Grace, what power can I have to write all this?.863.", hindi = "स्री असिपान, क्रिपा तुमरी करि; मै न कह︀यो, सभ तोहि बखान︀यो ॥८६३॥", punjabi = "ਹੇ ਕਾਲ ਪੁਰਖ! ਤੇਰੀ ਕ੍ਰਿਪਾ ਕਰਕੇ (ਗ੍ਰੰਥ ਸਿਰਜਿਆ ਜਾ ਸਕਿਆ ਹੈ)। (ਇਹ) ਮੈਂ ਨਹੀਂ ਕਿਹਾ, ਸਾਰਾ ਤੁਸੀਂ ਹੀ ਕਥਨ ਕੀਤਾ ਹੈ ॥੮੬੩॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-61", gurmukhi = "ਦੋਹਰਾ ॥", transliteration = "dohraa ||", translation = "DOHRA", hindi = "दोहरा ॥", punjabi = "ਦੋਹਰਾ", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-62", gurmukhi = "ਸਗਲ ਦੁਆਰ ਕਉ ਛਾਡਿ ਕੈ; ਗਹਿਓ ਤੁਹਾਰੋ ਦੁਆਰ ॥", transliteration = "sagal duaar kau chhaad kai; ghio tuhaaro duaar ||", translation = "O Lord! I have forsaken all other doors and have caught hold of only Thy door. O Lord! Thou has caught hold of my arm", hindi = "सगल दुआर कउ छाडि कै; गहिओ तुहारो दुआर ॥", punjabi = "ਸਾਰੇ ਦਰਾਂ ਨੂੰ ਛੱਡ ਕੇ, ਤੁਹਾਡਾ ਦਰ ਫੜਿਆ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "aarti-63", gurmukhi = "ਬਾਂਹਿ ਗਹੇ ਕੀ ਲਾਜ ਅਸ; ਗੋਬਿੰਦ ਦਾਸ ਤੁਹਾਰ ॥੮੬੪॥", transliteration = "baanh ghe kee laaj as; gobind daas tuhaar ||864||", translation = "I, Govind, am Thy serf, kindly take (care of me and) protect my honour.864.", hindi = "बांहि गहे की लाज अस; गोबिंद दास तुहार ॥८६४॥", punjabi = "ਤੁਹਾਨੂੰ ਬਾਂਹ ਫੜੇ ਦੀ ਲਾਜ ਹੈ, ਗੋਬਿੰਦ ਤੁਹਾਡਾ ਦਾਸ ਹਾਂ ॥੮੬੪॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L)
)
